// Native-only storage ABI. Actual addresses are written and consumed on the
// GPU; JavaScript sees only the browser's opaque resource objects. A logical
// renderer buffer can exceed the browser's per-shared-allocation size limit.
template<class T> struct OmwPaged {
    const unsigned long long* pages;
    T* direct;
    unsigned long long first;
    __device__ OmwPaged(const unsigned long long* table):pages(table),direct(nullptr),first(0) {}
    __device__ OmwPaged(T* pointer):pages(nullptr),direct(pointer),first(0) {}
    template<class U> __device__ OmwPaged(const OmwPaged<U>& other):pages(other.pages),direct(other.direct),first(other.first) {}
    __device__ T& operator[](unsigned long long index) const {
        index+=first;
        if(direct)return direct[index];
        unsigned long long bytes=index*sizeof(T);
        return *reinterpret_cast<T*>(pages[bytes>>26]+(bytes&67108863ull));
    }
    __device__ OmwPaged operator+(unsigned long long offset) const {
        OmwPaged result=*this;result.first+=offset;return result;
    }
};

// Scalar depth planes keep full resolution without unused color/normal storage.
__global__ void clear_compact_depth(const unsigned long long* omw_pages_target,unsigned int pixel_count,float depth) {
OmwPaged<float> target(omw_pages_target);

    unsigned int i=(blockIdx.x+blockIdx.y*gridDim.x)*blockDim.x+threadIdx.x;
    if(i<pixel_count)target[i]=depth;
}
__global__ void copy_depth_layout(const unsigned long long* omw_pages_source,const unsigned long long* omw_pages_target,unsigned int pixel_count,unsigned int source_compact,unsigned int target_compact) {
OmwPaged<const float> source(omw_pages_source);
OmwPaged<float> target(omw_pages_target);

    unsigned int i=(blockIdx.x+blockIdx.y*gridDim.x)*blockDim.x+threadIdx.x;
    if(i<pixel_count)target[target_compact!=0u?i:i*9u+4u]=source[source_compact!=0u?i:i*9u+4u];
}
__global__ void compact_depth_to_texture(const unsigned long long* omw_pages_target,const unsigned long long* omw_pages_texels,unsigned int width,unsigned int height,unsigned int offset) {
OmwPaged<const float> target(omw_pages_target);
OmwPaged<unsigned int> texels(omw_pages_texels);

    unsigned int i=(blockIdx.x+blockIdx.y*gridDim.x)*blockDim.x+threadIdx.x;
    if(i<width*height)texels[offset+(height-1u-i/width)*width+i%width]=__float_as_uint(target[i]);
}
